<?php

namespace Nawasara\Workspace\Database\Seeders;

use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\Log;
use Nawasara\Workspace\Services\NextcloudAdminClient;
use Nawasara\Workspace\Services\NextcloudException;
use Throwable;

/**
 * The 14 built-in Kisara templates (T-21, FSD FR-15) in the team folder
 * "Templat Kisara": readable by every employee, writable only by the
 * Nextcloud admin group.
 *
 *   php artisan db:seed --class="Nawasara\Workspace\Database\Seeders\BuiltinTemplateSeeder"
 *
 * Source files ship with this package in resources/templates/, generated by
 * tools/templates/generate.py (reproducible, byte-identical on every run).
 *
 * Idempotent and safe to re-run:
 *   - the folder is found by name, created only when missing;
 *   - group permissions are corrected to the wanted state (admin group 31,
 *     every other group read-only 1);
 *   - a file is uploaded only when it is missing or its sha256 differs from
 *     what Nextcloud holds, so a rerun with unchanged files writes nothing.
 *
 * Uses the admin account: this is Nawasara's control plane. Workspace Web
 * never does this; it reads the folder as the employee (ADR 0003).
 * Template metadata (names, order, scope) arrives with T-31; this seeder only
 * puts the files in place.
 */
class BuiltinTemplateSeeder extends Seeder
{
    private const MIME = [
        'docx' => 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
        'xlsx' => 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        'pptx' => 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
    ];

    public const READ = 1;

    public const ALL = 31; // read, write, create, delete, share

    public function __construct(private ?NextcloudAdminClient $nc = null) {}

    public function run(): void
    {
        $stats = $this->seed();

        $this->command?->info('Templat Kisara: '.json_encode($stats));
    }

    /**
     * @return array{configured: bool, folder_id: ?int, folder_created: bool, groups_fixed: int, files: int, created: int, updated: int, unchanged: int, failed: int}
     */
    public function seed(): array
    {
        $nc = $this->nc ?? app(NextcloudAdminClient::class);
        $folderName = (string) config('nawasara-workspace.templates.folder', 'Templat Kisara');
        $stats = ['configured' => true, 'folder_id' => null, 'folder_created' => false, 'groups_fixed' => 0,
            'files' => 0, 'created' => 0, 'updated' => 0, 'unchanged' => 0, 'failed' => 0];

        if (! $nc->isConfigured()) {
            Log::warning('workspace.templates.seed_skipped', ['reason' => 'nextcloud_not_configured']);
            $this->command?->warn('Grup Vault workspace belum diisi; templat tidak diunggah.');

            return ['configured' => false] + $stats;
        }

        $files = $this->sourceFiles();
        $started = microtime(true);
        Log::info('workspace.templates.seed_started', ['folder' => $folderName, 'files' => count($files)]);

        try {
            [$id, $created, $fixed] = $this->ensureFolder($nc, $folderName);
            $stats['folder_id'] = $id;
            $stats['folder_created'] = $created;
            $stats['groups_fixed'] = $fixed;
        } catch (Throwable $e) {
            Log::error('workspace.templates.seed_failed', ['stage' => 'folder', 'reason' => mb_substr($e->getMessage(), 0, 300)]);
            throw $e;
        }

        foreach ($files as $path) {
            $name = basename($path);
            $remotePath = $folderName.'/'.$name;
            $stats['files']++;

            try {
                $local = (string) file_get_contents($path);
                $remote = $nc->downloadFile($remotePath);

                if ($remote !== null && hash_equals(hash('sha256', $remote), hash('sha256', $local))) {
                    $stats['unchanged']++;

                    continue;
                }

                $ext = strtolower(pathinfo($name, PATHINFO_EXTENSION));
                $nc->uploadFile($remotePath, $local, self::MIME[$ext] ?? 'application/octet-stream');
                $stats[$remote === null ? 'created' : 'updated']++;
                Log::info('workspace.templates.uploaded', ['file' => $name, 'action' => $remote === null ? 'created' : 'replaced', 'bytes' => strlen($local)]);
            } catch (NextcloudException $e) {
                $stats['failed']++;
                Log::warning('workspace.templates.upload_failed', ['file' => $name, 'reason' => mb_substr($e->getMessage(), 0, 300)]);
            }
        }

        Log::info('workspace.templates.seed_finished', $stats + ['duration_ms' => (int) ((microtime(true) - $started) * 1000)]);

        return $stats;
    }

    /** @return list<string> absolute paths, sorted */
    public function sourceFiles(): array
    {
        // No GLOB_BRACE: it does not exist on musl (Alpine) builds of PHP.
        $files = array_filter(
            glob(dirname(__DIR__, 3).'/resources/templates/*') ?: [],
            fn ($f) => isset(self::MIME[strtolower(pathinfo($f, PATHINFO_EXTENSION))]),
        );
        sort($files);

        return $files;
    }

    /**
     * The folder with the wanted groups and permissions.
     *
     * Readers: the configured groups (the pilot group by default) plus every
     * `OPD-*` group that has a Folder OPD, i.e. every employee with an OPD.
     * A new OPD gets read access the next time this seeder runs.
     *
     * @return array{0: int, 1: bool, 2: int} id, created, groups corrected
     */
    private function ensureFolder(NextcloudAdminClient $nc, string $name): array
    {
        $adminGroup = (string) config('nawasara-workspace.templates.admin_group', 'admin');
        $readers = array_values(array_filter((array) config('nawasara-workspace.templates.reader_groups', []), 'is_string'));

        $folders = $nc->teamFolders();
        $folder = null;
        foreach ($folders as $f) {
            if ($f['mount_point'] === $name) {
                $folder = $f;
                break;
            }
        }
        foreach ($folders as $f) {
            foreach (array_keys($f['groups']) as $gid) {
                if (str_starts_with($gid, 'OPD-')) {
                    $readers[] = $gid;
                }
            }
        }
        $readers = array_values(array_diff(array_unique($readers), [$adminGroup]));

        $created = false;
        if ($folder === null) {
            $id = $nc->createTeamFolder($name);
            $folder = ['id' => $id, 'groups' => []];
            $created = true;
            Log::info('workspace.templates.folder_created', ['folder_id' => $id, 'name' => $name]);
        }
        $id = (int) $folder['id'];

        // The admin must be in the admin group to see the folder over WebDAV.
        // Checked first, so a rerun sends no write at all.
        if (! in_array($adminGroup, $nc->userGroups($nc->adminUser()), true)) {
            $nc->ensureGroup($adminGroup);
            $nc->addUserToGroup($nc->adminUser(), $adminGroup);
        }

        $want = [$adminGroup => self::ALL] + array_fill_keys($readers, self::READ);
        // Any other group already on the folder stays, but read-only: only
        // the admin group writes here.
        foreach ($folder['groups'] as $gid => $perm) {
            $want[$gid] ??= self::READ;
        }

        $fixed = 0;
        foreach ($want as $gid => $perm) {
            $have = $folder['groups'][$gid] ?? null;
            if ($have === $perm) {
                continue;
            }
            if ($have === null) {
                $nc->ensureGroup($gid);
                $nc->assignTeamFolderGroup($id, $gid, $perm);
            } else {
                $nc->setTeamFolderGroupPermissions($id, $gid, $perm);
            }
            $fixed++;
        }

        return [$id, $created, $created ? 0 : $fixed];
    }
}
